// Refreshes assets/adblock/easylist_domains.txt from EasyList.
//
//   dart run tools/update_ad_list.dart [path/to/easylist.txt]
//
// Without a path it downloads https://easylist.to/easylist/easylist.txt.
// Keeps only rules that block a whole ad domain (`||domain^`, optionally with
// third-party/type options), which is what the browser's content blocker uses.
// EasyList is dual licensed GPLv3 / CC BY-SA 3.0 (https://easylist.to); the
// generated file keeps that notice.
import 'dart:io';

Future<void> main(List<String> args) async {
  final text = args.isNotEmpty ? await File(args.first).readAsString() : await _download();

  const allowedOptions = {
    'third-party', '3p', 'script', 'popup', 'subdocument', 'image', //
    'xmlhttprequest', 'all', 'document', 'media', 'other',
  };
  final rule = RegExp(r'^\|\|([a-z0-9.-]+\.[a-z]{2,})\^(?:\$(.*))?$');
  final domains = <String>{};
  var version = '';
  for (final raw in text.split('\n')) {
    final line = raw.trim();
    if (line.startsWith('! Version:')) version = line.substring(10).trim();
    final m = rule.firstMatch(line);
    if (m == null) continue;
    final options = m.group(2);
    if (options != null && !options.split(',').every((o) => allowedOptions.contains(o.trim()))) continue;
    domains.add(m.group(1)!);
  }
  final sorted = domains.toList()..sort();
  final out = File('assets/adblock/easylist_domains.txt');
  await out.parent.create(recursive: true);
  await out.writeAsString(
    '# Ad domains from EasyList $version (https://easylist.to), CC BY-SA 3.0 / GPLv3.\n'
    '# Generated by tools/update_ad_list.dart. Do not edit by hand.\n'
    '${sorted.join('\n')}\n',
  );
  stdout.writeln('${sorted.length} ad domains written to ${out.path}');
}

Future<String> _download() async {
  final client = HttpClient();
  try {
    final response = await (await client.getUrl(Uri.parse('https://easylist.to/easylist/easylist.txt'))).close();
    if (response.statusCode != 200) throw HttpException('EasyList download failed: ${response.statusCode}');
    return await response.transform(const SystemEncoding().decoder).join();
  } finally {
    client.close();
  }
}
